ALTER TABLE stories ADD COLUMN photo_credit TEXT NOT NULL DEFAULT '';
-- Separate only unchanged bundled sample captions; preserve user-edited captions.
UPDATE stories SET caption='For everyone who stayed through the credits. Illustrative sample story.', photo_credit='Unsplash' WHERE id='demo-01' AND caption='For everyone who stayed through the credits. Photograph: Unsplash. Illustrative sample story.';
UPDATE stories SET published_json=json_set(published_json, '$.caption', 'For everyone who stayed through the credits. Illustrative sample story.', '$.photo_credit', 'Unsplash') WHERE id='demo-01' AND json_extract(published_json, '$.caption')='For everyone who stayed through the credits. Photograph: Unsplash. Illustrative sample story.';
